import { test, expect } from '@playwright/test';

const BASE_URL = process.env.TARGET_URL || 'https://adactinhotelapp.com/';
const USERNAME = process.env.TARGET_USERNAME || 'ADACTINFORQA';
const PASSWORD = process.env.TARGET_PASSWORD || '3U0515';

test('Valid booking generates order number', async ({ page }) => {
  // [Timeline] Navigate to base URL
  console.log('[Timeline] Navigate to base URL');
  await page.goto(BASE_URL);

  // [Timeline] Log in with valid credentials
  console.log('[Timeline] Log in with valid credentials');
  await page.locator('input#username').fill(USERNAME);
  await page.locator('input#password').fill(PASSWORD);
  await page.locator('input#login').click();
  await expect(page).toHaveURL(/SearchHotel\.php/);

  // [Timeline] Perform hotel search (precondition: user has completed search and selected a hotel)
  console.log('[Timeline] Perform hotel search');
  await expect(page.locator('input#username_show')).toHaveValue('Hello ADACTINFORQA!');
  await page.locator('select#location').selectOption({ label: 'Sydney' });
  await page.locator('select#hotels').selectOption({ label: 'Hotel Creek' });
  await page.locator('select#room_type').selectOption({ label: 'Standard' });
  await page.locator('select#room_nos').selectOption({ label: '1 - One' });
  await page.locator('input#datepick_in').fill('20/08/2026');
  await page.locator('input#datepick_out').fill('25/08/2026');
  await page.locator('select#adult_room').selectOption({ label: '1 - One' });
  await page.locator('select#child_room').selectOption({ label: '0 - None' });
  await page.locator('input#Submit').click();
  await expect(page).toHaveURL(/SelectHotel\.php/);

  // [Timeline] Select the first hotel (precondition: user selected a hotel)
  console.log('[Timeline] Select the first hotel');
  await page.locator('input#radiobutton_0').check();
  await page.locator('input#continue').click();
  await expect(page).toHaveURL(/BookHotel\.php/);

  // Now on BookHotel.php Ã¢â‚¬â€œ proceed with given steps
  // [Timeline] Fill in First Name
  console.log('[Timeline] Fill in First Name');
  await page.locator('input#first_name').fill('John');
  // [Timeline] Fill in Last Name
  console.log('[Timeline] Fill in Last Name');
  await page.locator('input#last_name').fill('Doe');
  // [Timeline] Fill in Billing Address
  console.log('[Timeline] Fill in Billing Address');
  await page.locator('textarea#address').fill('123 Test Street, Sydney, NSW');
  // [Timeline] Select Credit Card Type as VISA
  console.log('[Timeline] Select Credit Card Type as VISA');
  await page.locator('select#cc_type').selectOption({ label: 'VISA' });
  // [Timeline] Fill in Credit Card Number
  console.log('[Timeline] Fill in Credit Card Number');
  await page.locator('input#cc_num').fill('1234567890123456');
  // [Timeline] Select Expiry Month as December
  console.log('[Timeline] Select Expiry Month as December');
  await page.locator('select#cc_exp_month').selectOption({ label: 'December' });
  // [Timeline] Select Expiry Year as 2028
  console.log('[Timeline] Select Expiry Year as 2028');
  await page.locator('select#cc_exp_year').selectOption({ label: '2028' });
  // [Timeline] Fill in CVV Number
  console.log('[Timeline] Fill in CVV Number');
  await page.locator('input#cc_cvv').fill('123');
  // [Timeline] Click Book Now button
  console.log('[Timeline] Click Book Now button');
  await page.locator('input#book_now').click();

  // [Timeline] Assert redirection to BookingConfirm.php and numeric order number
  console.log('[Timeline] Assert redirection to BookingConfirm.php and numeric order number');
  await expect(page).toHaveURL(/BookingConfirm\.php/, { timeout: 15000 });
  const orderNumber = await page.locator('input#order_no').inputValue();
  expect(orderNumber).toMatch(/^\d+$/);
});

