  // Navigate to the Adactin Hotel Application
  await page.goto(BASE_URL, { waitUntil: 'networkidle' });
  console.log('Navigated to Adactin Hotel Portal');

  // Take a screenshot of the initial state
  await page.screenshot({ path: '01-initial-state.png' });

  // Perform Login with valid username but incorrect password
  await page.locator('#username').fill(USERNAME);
  await page.locator('#password').fill('WrongPassword123');
  await page.locator('#login').click();
  console.log('Filled credentials and clicked Login');

  // Wait a moment for the page to respond
  await page.waitForTimeout(2000);

